class Solution {
public:
    int minimumVisitedCells(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        if (m == 1 && n == 1) return 1;
        vector<int> dist(m * n, -1);
        // row DSU: for each row, parent over column indices 0..n (n = sentinel)
        vector<vector<int>> rp(m, vector<int>(n + 1));
        // column DSU: for each column, parent over row indices 0..m (m = sentinel)
        vector<vector<int>> cp(n, vector<int>(m + 1));
        for (int i = 0; i < m; ++i)
            for (int j = 0; j <= n; ++j) rp[i][j] = j;
        for (int j = 0; j < n; ++j)
            for (int i = 0; i <= m; ++i) cp[j][i] = i;

        auto find = [](vector<int>& p, int x) {
            while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; }
            return x;
        };

        vector<pair<int,int>> q;
        q.reserve(m * n);
        dist[0] = 1;
        q.push_back({0, 0});
        for (size_t h = 0; h < q.size(); ++h) {
            int i = q[h].first, j = q[h].second;
            int d = dist[i * n + j];
            int g = grid[i][j];
            // rightward moves in row i: columns j+1 .. j+g
            for (int k = find(rp[i], j + 1); k <= j + g && k < n; k = find(rp[i], k + 1)) {
                rp[i][k] = k + 1;
                if (dist[i * n + k] == -1) {
                    dist[i * n + k] = d + 1;
                    if (i == m - 1 && k == n - 1) return d + 1;
                    q.push_back({i, k});
                }
            }
            // downward moves in column j: rows i+1 .. i+g
            for (int k = find(cp[j], i + 1); k <= i + g && k < m; k = find(cp[j], k + 1)) {
                cp[j][k] = k + 1;
                if (dist[k * n + j] == -1) {
                    dist[k * n + j] = d + 1;
                    if (k == m - 1 && j == n - 1) return d + 1;
                    q.push_back({k, j});
                }
            }
        }
        return dist[m * n - 1];
    }
};
